test_suite:
test('ref.current holds the initial value', () => {
  const { result } = renderHook(() => useLatest(42));
  expect(result.current.current).toBe(42);
});

test('ref.current updates when value changes', () => {
  const { result, rerender } = renderHook(
    ({ v }) => useLatest(v),
    { initialProps: { v: 1 } }
  );
  rerender({ v: 99 });
  expect(result.current.current).toBe(99);
});

test('returns same ref object across renders', () => {
  const { result, rerender } = renderHook(
    ({ v }) => useLatest(v),
    { initialProps: { v: 'a' } }
  );
  const first = result.current;
  rerender({ v: 'b' });
  expect(result.current).toBe(first);
});

test('works with objects', () => {
  const obj1 = { x: 1 };
  const obj2 = { x: 2 };
  const { result, rerender } = renderHook(
    ({ v }) => useLatest(v),
    { initialProps: { v: obj1 } }
  );
  rerender({ v: obj2 });
  expect(result.current.current).toBe(obj2);
});

// __hidden__
test('works with null value', () => {
  const { result, rerender } = renderHook(
    ({ v }) => useLatest(v),
    { initialProps: { v: 'hello' as string | null } }
  );
  rerender({ v: null });
  expect(result.current.current).toBeNull();
});

solution:
import { useRef } from 'react';

export function useLatest<T>(value: T): React.MutableRefObject<T> {
  const ref = useRef(value);
  ref.current = value;
  return ref;
}
